function routeRead(){const parts=location.hash.slice(1).split("/");try{page=decodeURIComponent(parts[0]||"overview");selection=decodeURIComponent(parts[1]||"")}catch{page="overview";selection=""}if(!navItems().some(x=>x[0]===page)){page="overview";selection=""}}
function go(p,id=""){if(location.hash===route(p,id)){routeRead();render()}else location.hash=route(p,id)}
