function installListFilter(){let f=$("#filter-list"),pos=$("#position-filter");const update=()=>{const q=(f?.value||"").toLowerCase().trim(),p=pos?.value||"";let visible=0;document.querySelectorAll(".items .item").forEach(el=>{const ok=(!q||el.dataset.search.includes(q))&&(!p||el.dataset.positions.split(" ").includes(p));el.hidden=!ok;if(ok)visible++});const z=$("#list-empty");if(z)z.hidden=visible!==0};f?.addEventListener("input",update);pos?.addEventListener("change",()=>{dictPosition=pos.value;update()});update()}
