const positionCounts=()=>{const c={};V.dictionary.forEach(x=>{Object.values(typeof x.position==="object"?x.position:{one:x.position}).forEach(p=>{c[p]=(c[p]||0)+1})});return c};
function positionCards(){const counts=positionCounts();return '<div class="positions">'+V.positions.map(x=>'<button class="position '+posClass(x.id)+'" data-position="'+esc(x.label)+'"><strong>'+esc(posName(x.label))+'</strong><div class="number">'+(counts[x.label]||0)+'</div><span class="tiny muted">'+t("meanings","betekenissen")+' · '+esc(x.id)+'</span></button>').join("")+'</div>'}
function overview(){
 const stats=[["rules",V.rules.length,t("Normative rules","Normatieve regels")],["dictionary",V.dictionary.length,t("Dictionary entries","Woordenboekbegrippen")],["schemas",V.schemas.length,t("JSON schemas","JSON-schema's")],["rules",V.profiles.length,t("Conformance profiles","Conformiteitsprofielen")]];
 const example=V.examples.find(x=>x.data.id==="EX-SEM-MEMORY-001")||V.examples[0];
 const first=example?.data?.actors?.[0]?.core_actions?.[0], ai=first?.microstructures?.flatMap(m=>arr(m.ai_actions))||[];
 const aiLabels=[...new Set(ai)].map(x=>cap(V.ai_actions.find(a=>a.id===x)?.label||x));
 const flow=[["target",t("Learning goal","Leerdoel"),example?.data.goal],["person",t("Human action","Menselijke handeling"),first?.label],["ai",t("AI action","AI-handeling"),aiLabels.join(" · ")],["evidence",t("Evidence claim","Bewijsclaim"),cap(example?.data.claim_type||"none")]];
 const feature=(p,d)=>'<a class="panel feature" href="'+route(p)+'"><span class="feature-icon">'+icon(p)+'</span><div><h3>'+esc(titleOf(p))+'</h3><p>'+esc(d)+'</p></div>'+icon("arrow")+'</a>';
 const features=[["concepts",t("Read definitions and follow their actual relations.","Lees definities en volg hun vastgelegde relaties.")],["schemas",t("Inspect fields, required values and references. Download the original JSON.","Bekijk velden, verplichte waarden en verwijzingen. Download de JSON.")],["rules",t("See which rules can be checked by software and which require judgement.","Bekijk welke regels software kan toetsen en welke om een oordeel vragen.")],["evidence",t("Follow a rule to its recorded research claims and sources.","Volg een regel naar de vastgelegde onderzoeksclaims en bronnen.")],["cases",t("See who performs each operation in a worked example.","Bekijk wie welke handeling uitvoert in een voorbeeld.")],["adapters",t("Read the original model elements and their EAI mappings.","Bekijk de oorspronkelijke modelonderdelen en hun EAI-koppelingen.")]];
 return '<div class="hero"><div><span class="eyebrow">'+t("Open candidate specification","Open kandidaatstandaard")+'</span><h1>EAI Standard</h1><p class="lead">'+t("What does AI do, what does the learner or professional still do, and what can we establish from the evidence? The EAI Standard provides a common way to record these distinctions.","Wat doet AI, wat doet de leerling of professional nog zelf, en wat kunnen we vaststellen op basis van het bewijs? De EAI Standard biedt een gemeenschappelijke manier om dit vast te leggen.")+'</p><p class="sub">'+t("Model-independent. No overall quality score. No claim of certified effectiveness.","Onafhankelijk van het gebruikte onderwijsmodel. Geen totaalscore en geen bewezen effectiviteit op basis van conformiteit alleen.")+'</p><div class="actions"><a class="button primary" href="#concepts">'+t("Explore the standard","Bekijk de standaard")+icon("arrow")+'</a><a class="button" href="#schemas">'+t("Browse schemas","Bekijk schema’s")+'</a></div><div class="pills" style="margin-top:15px">'+pill(V.version,"accent")+pill("Apache-2.0")+(V.tag?'<a class="pill" href="'+data.repository+'/tree/'+esc(V.tag)+'">'+esc(V.tag)+'</a>':pill(t("Pinned source","Vaste bron")))+'</div></div><div class="hero-visual"><div class="visual-heading"><span class="eyebrow">'+t("From the example cases","Uit de voorbeeldsituaties")+'</span>'+link("cases",example?.data.id||"",t("Open case","Open casus"),"tiny")+'</div><div class="flow-column">'+flow.map(([ic,title,sub],i)=>(i?'<div class="flow-line"></div>':"")+'<div class="flow-node"><span class="node-icon">'+icon(ic)+'</span><div><strong>'+esc(title)+'</strong><span class="small">'+esc(sub||t("Not specified","Niet vastgelegd"))+'</span></div></div>').join("")+'</div><div class="tiny muted" style="margin-top:12px">'+t("Illustrative case, not measured learning evidence.","Fictief voorbeeld, geen gemeten leerresultaat.")+'</div></div></div><div class="stats">'+stats.map(([p,n,label])=>'<a class="stat" href="#'+p+'"><span class="number">'+n+'</span><span class="label">'+esc(label)+'</span></a>').join("")+'</div>'+section(t("Where does a concept get its meaning?","Waar komt de betekenis van een begrip vandaan?"),positionCards()+note(t("Counts include separate human and system meanings. The five positions are categories, not a quality scale.","De aantallen tellen afzonderlijke menselijke en technische betekenissen mee. De vijf posities zijn categorieën, geen kwaliteitsschaal.")),V.position_status==="proposal"?t("In this version the positions are still a proposal.","In deze versie zijn de posities nog een voorstel."):t("Select a position to see the related dictionary meanings.","Kies een positie om de bijbehorende betekenissen in het woordenboek te bekijken."))+section(t("Read and explore","Lezen en onderzoeken"),'<div class="grid3">'+features.map(([p,d])=>feature(p,d)).join("")+'</div>')+section(t("Version and source","Versie en bron"),'<div class="panel"><div class="pills">'+pill(V.version,"accent")+pill(V.tag?t("Git tag verified","Git-tag gecontroleerd"):t("Pinned source","Vaste bron"))+'</div><p style="margin:10px 0" class="small">'+t("This view is generated from the selected source commit. A build check is not a reference validator.","Deze weergave komt uit de gekozen broncommit. Een geslaagde build is geen referentievalidator.")+'</p><div class="pills">'+source("standard/public-interface.yaml",t("Normative manifest","Normatief manifest"))+link("versions","",t("Version history","Versiegeschiedenis"),"button small")+'<a class="button small" href="'+data.repository+'/actions">'+t("CI results","CI-resultaten")+'</a></div></div>');
}
function conceptView(){
 const items=Object.keys(V.definitions).map(id=>({id,label:termLabel(id),sub:id,search:V.definitions[id].definition}));
 const id=V.definitions[selection]?selection:(V.definitions.core_learning_action?"core_learning_action":items[0]?.id),d=V.definitions[id]||{};
 const outbound=V.relations.filter(r=>arr(r.domain).includes(id)),inbound=V.relations.filter(r=>arr(r.range).includes(id));
 const relNodes=(rels,side)=>{let nodes=rels.flatMap(r=>arr(side==="left"?r.domain:r.range).map(n=>({n,r})));return nodes.length?nodes.map(({n,r})=>'<div class="graph-node '+side+'">'+(V.definitions[n]?link("concepts",n,termLabel(n)):esc(cap(n)))+'<small>'+esc(human(r.label))+' · '+esc(r.id)+'</small></div>').join(""):'<div class="graph-empty">'+t("No recorded links","Geen vastgelegde relaties")+'</div>'};
 const all=[...new Map([...inbound,...outbound].map(r=>[r.id,r])).values()];
 const content='<div class="panel"><div class="pills">'+pill(t("Normative definition","Normatieve definitie"),"accent")+pill(id)+(d.position_ref?pill(posName(position(d.position_ref)?.label||d.position_ref)):"")+'</div><h2>'+esc(termLabel(id))+'</h2><p class="definition">'+esc(d.definition||"")+'</p>'+(lang==="nl"?note("De Engelse definitie is leidend. Nederlandse begrippen zijn bedoeld als ingang."):"")+(d.specialization_of?'<div class="chips">'+link("concepts",d.specialization_of,t("Specialization of ","Specialisatie van ")+termLabel(d.specialization_of),"chip")+'</div>':"")+(d.properties?'<h3>'+t("Properties","Eigenschappen")+'</h3><dl class="field-kv">'+Object.entries(d.properties).map(([k,v])=>'<div><dt>'+esc(human(k))+'</dt><dd>'+esc(String(v))+'</dd></div>').join("")+'</dl>':"")+'<div class="source-row">'+source("standard/definitions.yaml")+'</div></div><div class="panel"><h3>'+t("Recorded relations","Vastgelegde relaties")+'</h3><p class="small muted">'+t("Each line comes from the canonical relation file. Select another concept to follow it.","Elke lijn komt uit het normatieve relatiebestand. Kies een ander begrip om verder te kijken.")+'</p><div class="graph"><div class="graph-side">'+relNodes(inbound,"left")+'</div><div class="graph-center">'+esc(termLabel(id))+'</div><div class="graph-side">'+relNodes(outbound,"right")+'</div></div><div class="relation-list">'+all.map(r=>'<div class="relation"><span class="mono">'+esc(r.id)+'</span><strong>'+esc(cap(r.label))+'</strong><p>'+esc(r.description)+'</p></div>').join("")+'</div><div class="source-row">'+source("standard/relations.yaml")+'</div></div>';
 return pageHead(titleOf("concepts"),t("The definitions and relations that determine the meaning of the standard.","De definities en relaties die de betekenis van de standaard bepalen."))+'<div class="split">'+listPanel(items,"concepts",id)+'<div class="detail">'+content+'</div></div>'+section(t("Concept positions","Conceptposities"),'<div class="grid2">'+V.positions.map(x=>'<div class="panel"><div class="pills">'+pill(x.id)+pill(V.position_status==="canonical"?t("Canonical","Normatief"):t("Proposal","Voorstel"))+'</div><h3 style="margin-top:10px">'+esc(posName(x.label))+'</h3><p class="small">'+esc(x.definition)+'</p><div class="chips"><button class="button small" data-position="'+esc(x.label)+'">'+t("View meanings","Bekijk betekenissen")+'</button>'+source(V.position_source)+'</div></div>').join("")+'</div>');
}
function dictionaryView(){
 const items=V.dictionary.map(e=>({id:e.id,label:e.term?.[lang]||e.id,sub:e.term?.[lang==="nl"?"en":"nl"]||"",search:JSON.stringify(e),positions:Object.values(typeof e.position==="object"?e.position:{one:e.position})}));
 const selected=V.dictionary.find(e=>e.id===selection)||(dictPosition?V.dictionary.find(e=>Object.values(typeof e.position==="object"?e.position:{one:e.position}).includes(dictPosition)):null)||V.dictionary[0];
 if(!selected)return pageHead(titleOf("dictionary"),t("Bilingual explanations of EAI terms.","Tweetalige uitleg van EAI-begrippen."))+empty();
 const e=selected;const meanings=e.meanings?Object.entries(e.meanings).map(([key,m])=>({key,def:localized(m),pos:e.position?.[key]})):[{key:"",def:localized(e.definition),pos:e.position}];
 const refs=Object.entries(e.eai_refs||{}).map(([k,values])=>'<div class="subheading">'+esc(human(k))+'</div><div class="chips">'+arr(values).map(v=>{if(typeof v!=="string")return pill(sjson(v));if(V.definitions[v])return link("concepts",v,termLabel(v),"chip");if(V.rules.some(r=>r.id===v))return link("rules",v,v,"chip");if(V.dictionary.some(r=>r.id===v))return link("dictionary",v,termLabel(v),"chip");if(V.files.includes(v))return source(v,v);return pill(v)}).join("")+'</div>').join("");
 return pageHead(titleOf("dictionary"),t("Read both language editions. Explanations are not normative definitions.","Lees beide taalversies. De uitleg is geen normatieve definitie."))+'<div class="split">'+listPanel(items,"dictionary",e.id,true)+'<div class="detail"><div class="panel"><div class="pills">'+pill(t("Informative","Toelichtend"))+pill(human(e.label))+'</div><h2>'+esc(e.term?.[lang]||e.id)+'</h2><p class="muted small">'+esc(e.term?.[lang==="nl"?"en":"nl"]||"")+'</p>'+meanings.map(m=>'<div class="meaning '+posClass(m.pos)+'"><div class="pills">'+pill(posName(m.pos),"accent")+(m.key?pill(cap(m.key)):"")+'</div><p style="margin-top:8px">'+esc(m.def)+'</p></div>').join("")+(e.why?'<h3>'+t("Why it matters","Waarom dit ertoe doet")+'</h3><p>'+esc(localized(e.why))+'</p>':"")+(e.practical_use?'<h3>'+t("In practice","In de praktijk")+'</h3><p>'+esc(localized(e.practical_use))+'</p>':"")+(e.related?.length?'<h3>'+t("Related terms","Verwante begrippen")+'</h3><div class="chips">'+e.related.map(x=>link("dictionary",x,termLabel(x),"chip")).join("")+'</div>':"")+'<div class="source-row">'+source("dictionary/terms.yaml")+'</div></div>'+(refs?'<div class="panel"><h3>'+t("References in the standard","Verwijzingen naar de standaard")+'</h3>'+note(t("A reference links concepts; it is not automatically an equivalence.","Een verwijzing legt een verband. Begrippen zijn daarmee niet automatisch gelijk."))+refs+'</div>':"")+'</div></div>';
}
function schemaRef(ref,schema){try{const target=new URL(ref,new URL(schema.url,location.href));const base=new URL(".",location.href);if(target.origin===base.origin&&target.pathname.startsWith(base.pathname)){const path=decodeURIComponent(target.pathname.slice(base.pathname.length));const match=V.schemas.find(s=>s.url===path);if(match&&match.path!==schema.path)return link("schemas",match.path,ref,"chip");return '<a class="chip" href="'+esc(target.href)+'" target="_blank" rel="noopener">'+esc(ref)+'</a>'}}catch{}return '<code>'+esc(ref)+'</code>'}
function schemaTree(s,name,schema,required=false,depth=0){
 if(typeof s!=="object"||s===null)return '<div class="field-kv"><dt>'+esc(name)+'</dt><dd>'+esc(fieldText(s))+'</dd></div>';
 const type=Array.isArray(s.type)?s.type.join(" | "):s.type||((s.$ref)?t("reference","verwijzing"):s.properties?"object":"");
 const child=[];const req=s.required||[];for(const [key,value] of Object.entries(s.properties||{}))child.push(schemaTree(value,key,schema,req.includes(key),depth+1));
 if(s.items!==undefined)child.push(schemaTree(s.items,"items",schema,false,depth+1));
 for(const [key,val] of Object.entries(s.$defs||{}))child.push(schemaTree(val,"$defs / "+key,schema,false,depth+1));
 for(const key of ["allOf","anyOf","oneOf","prefixItems"])if(s[key])s[key].forEach((v,i)=>child.push(schemaTree(v,key+" ["+(i+1)+"]",schema,false,depth+1)));
 for(const key of ["if","then","else","not","additionalProperties","contains","propertyNames","unevaluatedProperties"])if(s[key]&&typeof s[key]==="object")child.push(schemaTree(s[key],key,schema,false,depth+1));
 const skip=new Set(["title","description","type","properties","required","items","$defs","$ref","$dynamicRef","allOf","anyOf","oneOf","prefixItems","if","then","else","not","contains","propertyNames","unevaluatedProperties","additionalProperties"]);
 const kv=Object.entries(s).filter(([k])=>!skip.has(k)).map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(fieldText(v))+'</dd></div>');
 if(typeof s.additionalProperties==="boolean")kv.push('<div><dt>additionalProperties</dt><dd>'+String(s.additionalProperties)+'</dd></div>');
 const body=(s.description?'<p class="field-desc">'+esc(s.description)+'</p>':"")+(s.$ref?'<div class="chips">'+schemaRef(s.$ref,schema)+'</div>':"")+(s.$dynamicRef?'<div class="chips">'+schemaRef(s.$dynamicRef,schema)+'</div>':"")+(kv.length?'<dl class="field-kv">'+kv.join("")+'</dl>':"")+child.join("");
 return '<details class="field-group" '+(depth===0?"open":"")+'><summary><span class="field-title">'+esc(name)+'</span>'+(type?'<span class="field-type">'+esc(type)+'</span>':"")+(required?pill(t("required","verplicht"),"accent"):"")+'</summary><div class="field-body">'+(body||'<span class="small muted">'+t("No further constraints","Geen verdere beperkingen")+'</span>')+'</div></details>';
}
async function fillSchema(s){const serial=++loadSerial,host=$("#schema-body");if(!host)return;try{const res=await fetch(s.url);if(!res.ok)throw Error("HTTP "+res.status);const raw=await res.text(),obj=JSON.parse(raw);if(serial!==loadSerial||!$("#schema-body"))return;const id=$("#schema-id");if(id)id.textContent=obj.$id||"";$("#schema-body").innerHTML=schemaMode==="json"?'<pre id="schema-raw">'+esc(raw)+'</pre>':schemaTree(obj,obj.title||s.title,s,false,0);$("#copy-id")?.addEventListener("click",()=>copy(obj.$id||""));$("#copy-json")?.addEventListener("click",()=>copy(raw));}catch(e){if(serial===loadSerial&&$("#schema-body"))$("#schema-body").innerHTML=note(t("Could not load the published schema: ","Het gepubliceerde schema kon niet worden geladen: ")+e.message,"warn")}}
